import{_ as s,c as n,a as e,o as l}from"./app-C_dHcy8Q.js";const i={};function c(p,a){return l(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="远程访问-网页-rdp-ssh-方案设计" tabindex="-1"><a class="header-anchor" href="#远程访问-网页-rdp-ssh-方案设计"><span>远程访问（网页 RDP/SSH）方案设计</span></a></h1><p>面向 Croupier 平台，将“服务器的登录与操作”纳入统一入口并留痕审计的可行方案整理。遵循 KISS/YAGNI：本设计先给出稳妥选型与最小闭环，后续按优先级扩展。</p><h2 id="目标与范围" tabindex="-1"><a class="header-anchor" href="#目标与范围"><span>目标与范围</span></a></h2><ul><li>通过浏览器访问服务器的 RDP/SSH（必要时 VNC/KVM），无需客户端插件</li><li>接入平台 RBAC/审批流，做到“谁在何时访问了哪台机器”的可追踪</li><li>支持会话录制（桌面/终端）与操作日志留存，安全受控（禁用高风险重定向）</li><li>兼容多网络环境（内网/DMZ/公网），可水平扩展</li></ul><h2 id="方案选型-结论" tabindex="-1"><a class="header-anchor" href="#方案选型-结论"><span>方案选型（结论）</span></a></h2><ul><li>优先：Apache Guacamole（开源、成熟、无 Agent，WebSocket + Canvas 前端，guacd 作为协议网关） <ul><li>协议：RDP、SSH、VNC</li><li>审计：会话录屏（.guac）、SSH 命令录制（typescript）、连接历史入库</li><li>集成：数据库/LDAP/OIDC/2FA；REST API 管理连接和用户</li></ul></li><li>备选/增强：MeshCentral（Node.js + Agent） <ul><li>优点：穿透 NAT、资产管理、广泛审计与事件，多端控制能力强</li><li>代价：需部署 Agent、引入与运维成本更高</li></ul></li></ul><p>推荐：以 Guacamole 为基础能力，后续按需补充 MeshCentral 作为“有 Agent 的深度管控”补充（双栈）。</p><h2 id="推荐架构与拓扑" tabindex="-1"><a class="header-anchor" href="#推荐架构与拓扑"><span>推荐架构与拓扑</span></a></h2><ul><li>控制面：Croupier（内网）统一 RBAC/审批/审计 → 反代/单点登录到 Guacamole Web（DMZ/内网）</li><li>协议面：浏览器 → WebSocket → Guacamole Web → guacd → 目标 RDP/SSH 主机（guacd 与目标机同域/隧道可达）</li><li>存储与审计： <ul><li>会话历史：Guacamole DB → 周期同步/直连查询写入 ClickHouse（统一审计视图）</li><li>会话录制：文件存储（NAS/对象存储），索引与元数据入库，访问经审批与临时凭证</li></ul></li></ul><h2 id="能力映射与安全控制" tabindex="-1"><a class="header-anchor" href="#能力映射与安全控制"><span>能力映射与安全控制</span></a></h2><ul><li>认证/授权： <ul><li>首选 OIDC/反向代理头部认证（由 Croupier SSO 透传），开启 2FA（TOTP）</li><li>Croupier 侧按“主机/环境/标签”做授权，调用 Guacamole REST API 动态创建/启用连接</li></ul></li><li>审计留痕： <ul><li>连接历史：用户、时间、目标、时长、来源 IP</li><li>录制：RDP 录屏（.guac）、SSH typescript；支持命名模板与集中存放</li></ul></li><li>限制策略： <ul><li>禁用非必要通道（文件、打印、剪贴板）</li><li>仅 HTTPS 暴露，WAF 与速率限制；外网访问必须通过审批</li></ul></li></ul><h2 id="与-croupier-的集成设计-最小闭环" tabindex="-1"><a class="header-anchor" href="#与-croupier-的集成设计-最小闭环"><span>与 Croupier 的集成设计（最小闭环）</span></a></h2><ol><li>身份与入口 <ul><li>前端：在 Web 中以 IFrame/反代路径嵌入 Guacamole 控制台（/ops/remote）</li><li>单点：由反向代理注入登录标识（OIDC/OAuth2 Proxy），Guacamole 侧启用对应模块</li></ul></li><li>授权与审批 <ul><li>Croupier 资源模型：Host（主机）、HostGroup（生产/预发/测试）、Env（dev/stage/prod）</li><li>高危访问（生产）走审批流，审批通过后生成“临时连接/短期令牌”，到期自动失效</li></ul></li><li>审计归集 <ul><li>连接历史同步至 ClickHouse：任务周期拉取或 DB 视图直连</li><li>录制文件索引入库：路径、时长、操作者、目标；文件存储以生命周期策略管理</li></ul></li><li>安全策略 <ul><li>默认禁用 RDP 文件/打印/剪贴板；SSH 禁用 SFTP（按需启用白名单）</li><li>审计员角色可查看录制；普通用户仅能发起连接不可访问他人录制</li></ul></li></ol><h2 id="guacamole-关键配置-示例" tabindex="-1"><a class="header-anchor" href="#guacamole-关键配置-示例"><span>Guacamole 关键配置（示例）</span></a></h2><ul><li>RDP 连接参数： <ul><li><code>recording-path=/var/recordings/rdp</code></li><li><code>recording-name=\\\${GUAC_USERNAME}-\\\${GUAC_DATE}.guac</code></li><li><code>create-recording-path=true</code></li><li><code>disable-clipboard=true, enable-audio=false, enable-drive=false</code>（按需）</li></ul></li><li>SSH 连接参数： <ul><li><code>typescript-path=/var/recordings/ssh</code></li><li><code>typescript-name=\\\${GUAC_USERNAME}-\\\${GUAC_DATE}</code></li><li><code>create-typescript-path=true</code></li></ul></li><li>认证与 SSO： <ul><li>数据库/MySQL/Postgres</li><li>OIDC/TOTP 模块（与反向代理/OAuth2 Proxy 配合）</li></ul></li></ul><h2 id="最小化部署骨架-示意-compose" tabindex="-1"><a class="header-anchor" href="#最小化部署骨架-示意-compose"><span>最小化部署骨架（示意 Compose）</span></a></h2><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">services</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">guacd</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> guacamole/guacd<span class="token punctuation">:</span>1.5.5</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token key atrule">db</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> mysql<span class="token punctuation">:</span><span class="token number">8</span></span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">MYSQL_ROOT_PASSWORD</span><span class="token punctuation">:</span> rootpass</span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> guac<span class="token punctuation">-</span>mysql<span class="token punctuation">:</span>/var/lib/mysql</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token key atrule">guacamole</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> guacamole/guacamole<span class="token punctuation">:</span>1.5.5</span>
<span class="line">    <span class="token key atrule">depends_on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>guacd<span class="token punctuation">,</span> db<span class="token punctuation">]</span></span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">MYSQL_HOSTNAME</span><span class="token punctuation">:</span> db</span>
<span class="line">      <span class="token key atrule">MYSQL_DATABASE</span><span class="token punctuation">:</span> guacamole_db</span>
<span class="line">      <span class="token key atrule">MYSQL_USER</span><span class="token punctuation">:</span> guacamole_user</span>
<span class="line">      <span class="token key atrule">MYSQL_PASSWORD</span><span class="token punctuation">:</span> guacpass</span>
<span class="line">      <span class="token key atrule">GUACD_HOSTNAME</span><span class="token punctuation">:</span> guacd</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">&quot;8081:8080&quot;</span></span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">guac-mysql</span><span class="token punctuation">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注：首次部署需执行官方 initdb.sql 初始化数据库；生产环境放置在反向代理后并启用 HTTPS、WAF、限流与 OIDC/2FA。</p><h2 id="meshcentral-作为补充-何时考虑" tabindex="-1"><a class="header-anchor" href="#meshcentral-作为补充-何时考虑"><span>MeshCentral 作为补充（何时考虑）</span></a></h2><ul><li>场景：需要穿透 NAT/零信任、设备资产管理、远程电源/KVM，更强的主机侧审计</li><li>代价：需要安装 Agent、更多的服务端维护与升级</li><li>可与 Guacamole 并存：有 Agent 的主机走 MeshCentral，无 Agent 的主机走 Guacamole</li></ul><h2 id="里程碑规划-建议" tabindex="-1"><a class="header-anchor" href="#里程碑规划-建议"><span>里程碑规划（建议）</span></a></h2><ul><li>M1（PoC 1-2 天）：起 Guacamole（录制开启）→ 反代 HTTPS → 测试 RDP/SSH 连接与录制 → 导出连接历史</li><li>M2（集成 3-5 天）：Croupier 中增“远程访问”资源与审批 → 适配 Guacamole REST（临时连接/令牌）→ 审计元数据入 ClickHouse 与页面查询</li><li>M3（生产化 3-7 天）：对象存储/加密/生命周期、审计员权限、黑白名单策略、WAF/限流、告警与容量监控</li><li>M4（可选）：MeshCentral 双栈、敏感操作水印、录制检索（OCR/全文索引）</li></ul><h2 id="风险与边界" tabindex="-1"><a class="header-anchor" href="#风险与边界"><span>风险与边界</span></a></h2><ul><li>录制体积与保留周期：需容量规划（对象存储/压缩/归档）</li><li>安全合规：录屏涉及敏感信息，严格分权与审批；访问录制应有审计</li><li>网络可达性：guacd 到目标主机需同域或经隧道；零信任/SDP 可引入但复杂度上升</li></ul><h2 id="结论" tabindex="-1"><a class="header-anchor" href="#结论"><span>结论</span></a></h2><ul><li>近期以 Guacamole 为“网页 RDP/SSH 网关 + 审计录制”的基础能力，快速纳管服务器访问</li><li>通过 Croupier 统一入口与 RBAC/审批/审计，打通最小闭环</li><li>需要更深控时再引入 MeshCentral（双栈），逐步完善</li></ul>`,26)])])}const u=s(i,[["render",c]]),o=JSON.parse('{"path":"/ops/remote-access-web.html","title":"远程访问（网页 RDP/SSH）方案设计","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1763326585000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":3,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"4651abc2dc4ea79d9d7986013ce873f113d7383f","time":1763326585000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): add ClickHouse schema + example queries; link from overview\\\\ndocs(metrics,ops): publish pages and escape MDX-sensitive tokens\\\\ndocs(sdk): add JS signature example"},{"hash":"0ac3783c0cafbb7e76dd3fb0484cad90c77386b8","time":1763325744000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): fix unresolved links; add missing pages; harden MDX; CI link check\\\\n\\\\nfeat(analytics): add public ingestion service (cmd/analytics-ingest), Makefile targets, Dockerfiles; compose service; fix worker image\\\\n\\\\nchore(docs): adjust config to ignore node_modules in docs plugin; remove duplicate index page\\\\n\\\\nrefactor(docs): escape MDX-sensitive chars and fence YAML blocks"},{"hash":"9183a71d141f253f6ac217641420d573f5ab8bda","time":1763187722000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(ops): add web-based RDP/SSH design (Guacamole/MeshCentral, audit, integration plan)"}]},"filePathRelative":"ops/remote-access-web.md"}');export{u as comp,o as data};
